function createFakeChild(pid: number, pipes = true) {
	const stream = () => Object.assign(new EventEmitter(), { destroy() {} });
	return Object.assign(new EventEmitter(), { pid, stdout: pipes ? stream() : undefined, stderr: pipes ? stream() : undefined });
}

function createDeferred<T>() {
	let resolve!: (value: T | PromiseLike<T>) => void;
	const promise = new Promise<T>(done => { resolve = done; });
	return { promise, resolve };
}

/** A live host child with a controllable exact-tree barrier. */
function createDeferredTreeExitRunner(options: { deferFirstTreeExit?: boolean } = {}) {
	const spawned = createDeferred<void>();
	const killStarted = createDeferred<void>();
	const treeExit = createDeferred<boolean>();
	let child: ReturnType<typeof createFakeChild> | undefined;
	let waits = 0;
	let kills = 0;
	const tracked = {
		get child() { return child!; },
		ownershipReady: Promise.resolve(),
		killed: () => kills > 0,
		timedOut: () => false,
		markSurvival: () => {},
		killTree: () => { kills++; killStarted.resolve(); },
		// Cleanup gets the first wait; the command-result close handler gets an
		// independently settled exact-barrier observation while cleanup is paused.
		waitForTreeExit: async () => ++waits === 1 && options.deferFirstTreeExit !== false ? treeExit.promise : true,
	};
	return {
		runner: { nonDurable: true, spawn: () => {
			child = createFakeChild(910_111);
			spawned.resolve();
			return tracked as any;
		} },
		spawned: spawned.promise,
		killStarted: killStarted.promise,
		releaseTreeExit: () => treeExit.resolve(true),
		closeNormally: () => {
			child!.emit("exit", 0, null);
			child!.emit("close", 0, null);
		},
		tracked,
		waits: () => waits,
		kills: () => kills,
	};
}

function createCancellationGateFixture(goalId: string, gateId: string, signalId: string) {
	const signal: any = {
		id: signalId, goalId, gateId, sessionId: "test-session", timestamp: 1,
		commitSha: "test-commit", content: "", metadata: {},
		verification: { status: "running", steps: [] },
	};
	const gate: any = {
		id: gateId, name: "Tracked cleanup", status: "running", dependsOn: [],
		verify: [{ name: "tracked command", type: "command", run: "true" }], signals: [signal],
	};
	const verificationUpdates: any[] = [];
	const gateStore = {
		getGate: (requestedGoalId: string, requestedGateId: string) =>
			requestedGoalId === goalId && requestedGateId === gateId ? gate : undefined,
		updateSignalVerification: (requestedSignalId: string, verification: any) => {
			if (requestedSignalId !== signalId) throw new Error("unexpected signal update");
			signal.verification = verification;
			verificationUpdates.push(verification);
		},
		updateGateStatus: (requestedGoalId: string, requestedGateId: string, status: string) => {
			if (requestedGoalId !== goalId || requestedGateId !== gateId) throw new Error("unexpected gate update");
			gate.status = status;
		},
	};
	return { signal, gate, gateStore, verificationUpdates };
}

/** Deterministic cleanup-failure seams: no OS process or wall-clock race. */
function createUnverifiedTreeRunner(options: { pid: number; killed: boolean; timedOut: boolean; closes?: boolean }) {
	const { pid, killed, timedOut, closes = true } = options;
	return {
		nonDurable: true,
		spawn: () => {
			const child = createFakeChild(pid);
			const tracked = {
				child, killed: () => killed, timedOut: () => timedOut, markSurvival: () => {}, killTree: () => {},
				waitForTreeExit: async () => false,
			};
			queueMicrotask(() => {
				child.emit("exit", timedOut ? null : 0, timedOut ? "SIGTERM" : null);
				if (closes) child.emit("close", timedOut ? null : 0, timedOut ? "SIGTERM" : null);
			});
			return tracked as any;
		},
	};
}

/** A child whose ownership witness has not acknowledged when cancellation arrives. */
function createPreReadinessRunner() {
	let acknowledgeOwnership!: () => void;
	let killCalls = 0;
	const ownershipReady = new Promise<void>(resolve => { acknowledgeOwnership = resolve; });
	return {
		nonDurable: true,
		acknowledgeOwnership: () => acknowledgeOwnership(),
		killCalls: () => killCalls,
		spawn: () => {
			const child = createFakeChild(910_006);
			let closed = false;
			const close = () => {
				if (closed) return;
				closed = true;
				child.emit("exit", null, "SIGTERM");
				child.emit("close", null, "SIGTERM");
			};
			return {
				child, ownershipReady, killed: () => killCalls > 0, timedOut: () => false, markSurvival: () => {},
				killTree: () => { killCalls++; close(); }, waitForTreeExit: async () => closed,
			} as any;
		},
	};
}

function setActiveCommandVerification(
	harness: any,
	goalId: string,
	gateId: string,
	signalId: string,
	names = ["step"],
	options: { commandSpawnState?: "queued" | "spawned" } = {},
) {
	const startedAt = Date.now();
	const commandSpawnState = options.commandSpawnState ?? "queued";
	(harness as any).activeVerifications.set(signalId, {
		goalId, gateId, signalId, overallStatus: "running", startedAt, currentPhase: 0,
		steps: names.map(name => ({
			name, type: "command", status: "running", startedAt, commandSpawnState,
			...(commandSpawnState === "spawned" ? { commandSpawnedAt: startedAt } : {}),
		})),
	});
}

async function startFakeTreeStep(kind: "timeout" | "cancel", tmp: string) {
	const broadcasts: any[] = [];
	const harness = makeHarness({ commandStepRunner: createFakeVerificationCommandRunner() }, broadcasts);
	const goalId = `goal-${kind}`;
	const gateId = `gate-${kind}`;
	const signalId = kind === "timeout" ? "sig-timeout-1" : "sig-cancel-1";
	const streamCtx = { goalId, gateId, signalId, stepIndex: 0 };
	setActiveCommandVerification(harness, goalId, gateId, signalId);
	const stepPromise = (harness as any).runCommandStep(fakeTreeCommand(), tmp, 60, false, streamCtx, undefined, undefined);
	const registered = await poll(() => (harness as any)._trackedCommandChildren.size > 0, 3000);
	assert.ok(registered, "tracked child should be registered shortly after spawn");
	const pidsReady = await poll(() => {
		const out = (harness as any).activeVerifications.get(signalId)?.steps?.[0]?.output ?? "";
		return /PARENT_PID=\d+/.test(out) && /CHILD_PID=\d+/.test(out);
	}, 3000);
	assert.ok(pidsReady, `fake command should stream both pid markers before ${kind}`);
	assert.ok(
		broadcasts.some(e => e.type === "gate_verification_step_output" && /PARENT_PID=\d+/.test(e.text ?? "")),
		"stdout marker should be broadcast as live step output",
	);
	return { broadcasts, harness, goalId, gateId, signalId, stepPromise };
}

